INSERT INTO client_contracts (contract_code, unit_id, start_date, end_date, description, service_type_id,
  payroll_window_id, billing_type_id, gst_option, status, approval_status, approved_at, record_type)
SELECT 'CON15999', u.id, '2026-05-21'::date, '2026-12-20'::date, 'L&T Finance Ltd — SIKH VILLAGE SECUNDERABAD (Telangana); rate card: Un-Armed Guard 12Hrs Telangana (Image 3)', 'b10a1dd8-116e-4c1d-856e-4b3785c04bd1', '5e900b36-3cca-4137-a923-57bfe7910641', '70f409c8-2eb6-4b44-bbae-2fe15a566b6d', 'igst',
  CASE WHEN '2026-12-20'::date < current_date THEN 'expired' ELSE 'active' END, 'approved', now(), 'client'
FROM units u WHERE u.code='CLI4342'
  AND NOT EXISTS (SELECT 1 FROM client_contracts c WHERE c.contract_code='CON15999');

